(* [comment removed for export] *)
Definition leaf_chkA (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      match CH2.ret_of GA.RETS i k with
      | Some j =>
          match nth_error GA.CPS j with
          | Some cj =>
              (Nat.eqb i 0 && Nat.eqb j 1 && Z.eqb pc PC_SM3 && Z.eqb (SR.ps_pc ps) PC_SM3
               && CH2.blocks_eqb (nth i GA.BLS []) [] && CH2.blocks_eqb (nth j GA.BLS []) [] && CHA.frames_eqb (nth i FFSA []) [] && CHA.frames_eqb (nth j FFSA []) FRM
               && CHA.foot_chk GAT.NF GA.HDECL c [] [] && CBA.regions_eqb (CC.cp_F c) CPF0
               && match CHA.custom_chk GAT.NF GA.HDECL GAT.SCELLS GAT.GLO GAT.GHI 512 1 [] [] [] (NEWS_SM ps cj) None c ps cj [] [] [] FRM with
                  | Some ci => (Nat.eqb (CH2.ci_nx ci) 40 && Z.eqb (CH2.ci_csp ci) (-96))%bool | None => false end)%bool
          | None => false
          end
      | None =>
          (Nat.eqb i 1 && Z.eqb pc JUNC && junc_chk GAT.NF c ps GB.cp0 FKNEWS && fsh_ok cells && kd_ok c && Nat.leb 46 (CC.cp_nx c)
           && CH2.blocks_eqb (nth i GA.BLS []) [] && CHA.frames_eqb (nth i FFSA []) FRM && CHA.foot_chk GAT.NF GA.HDECL c [] FRM && CBA.regions_eqb (CC.cp_F c) CPF
           && has cells (KWord (SA FE 504) 8 FLE) && CL.ps_reg_is ps 2 (APC.eaddz (EVar 2) (-96)))%bool
      end
  end.
(* [comment removed for export] *)
Definition leaf_chkB (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      match CH2.ret_of GB.RETS i k with
      | Some j =>
          match nth_error GB.CPS j with
          | Some cj =>
              (Nat.eqb j (i + 1) && CH2.blocks_eqb (nth i GB.BLS []) [] && CH2.blocks_eqb (nth j GB.BLS []) [] && CHA.frames_eqb (nth i FFSB []) FRM && CHA.frames_eqb (nth j FFSB []) FRM
               && CHA.foot_chk GBT.NF GB.HDECL c [] FRM && (Nat.eqb i 17 || fsh_ok cells) && kd_ok c && Nat.leb 46 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF
               && has cells (KWord (SA FE 504) 8 FLE) && has cells (KZero (SA (CHA.SRL3 VE) SBz) (ELit 51)) &&
              if Z.eqb pc PC_AMEMSET then
                match MSITE i with
                | Some (base, off, n) =>
                    (Z.eqb (SR.ps_pc ps) PC_AMEMSET
                     && isSome (CHA.custom_chk GBT.NF GB.HDECL GBT.SCELLS GBT.GLO GBT.GHI 2560 0 [] FRM [(EAlu Instr.ALU_ADD base (ELit off), 0, ELit n)] (NEWS_MS base off n) (Some (EAlu Instr.ALU_ADD base (ELit off))) c ps cj [] FRM [] FRM)
                     && CL.ps_reg_is ps 10 (EAlu Instr.ALU_ADD base (ELit off)) && CL.ps_reg_is ps 11 (ELit 0) && CL.ps_reg_is ps 12 (ELit n))%bool
                | None => false
                end
              else if Z.eqb pc PC_AMEMCPY then
                match MCSITE i with
                | Some (doff, soff) =>
                    (Z.eqb (SR.ps_pc ps) PC_AMEMCPY
                     && match CHA.custom_chk GBT.NF GB.HDECL GBT.SCELLS GBT.GLO GBT.GHI 2560 0 [] FRM [(IAV doff, 0, ELit 24)] (NEWS_MC cj doff 24) (Some (IAV doff)) c ps cj [] FRM [] FRM with
                        | Some ci => copy_ok cells (CH2.ci_nx ci) cj doff soff 24 | None => false end
                     && CL.ps_reg_is ps 10 (IAV doff) && CL.ps_reg_is ps 11 (IAF soff) && CL.ps_reg_is ps 12 (ELit 24))%bool
                | None => false
                end
              else if Z.eqb pc PC_SETSH then
                (Z.eqb (SR.ps_pc ps) PC_SETSH && Nat.eqb i 17
                 && match CHA.custom_chk GBT.NF GB.HDECL GBT.SCELLS GBT.GLO GBT.GHI 256 0 [] FRM [(CHA.SRL3 FE, SBz, ELit 64)] (STAT ++ FLAGN) None c ps cj [] FRM [] FRM with
                    | Some ci => (Z.eqb (CH2.ci_csp ci) (-96) && Nat.leb (CC.cp_nx c) (CH2.ci_nx ci))%bool | None => false end
                 && CL.ps_reg_is ps 10 (EAlu Instr.ALU_ADD (CHA.SRL3 FE) (ELit SBz)) && CL.ps_reg_is ps 11 (ELit 64))%bool
              else false)%bool
          | None => false
          end
      | None =>
          (Z.eqb pc RETPC && Nat.eqb i 18 && CBA.exit_base_chk GBT.NF RETPC c ps && CBA.regions_eqb (CC.cp_F c) CPF13 && CH2.blocks_eqb (nth i GB.BLS []) []
           && CHA.frames_eqb (nth i FFSB []) FRM
           && match CHA.retire_chk GBT.NF GB.HDECL c [] FRM with Some fl => expr_eqb fl FLE | None => false end
           && has cells (KWord (SA FLE 0) 1 (ELit 0)) && CL.ps_reg_is ps 10 FLE
           && exit_cells cells && existsb flags_cell cells && existsb enable_cell cells && kd_ok c && Nat.leb 46 (CC.cp_nx c))%bool
      end
  end.
